//! Authored, uncompiled/unrun private-engine regressions. Generated byte fixtures
//! isolate transaction behavior; they are not PNG/media or native qualification.
use super::*;
use std::{cell::Cell, io::Write, path::{Path,PathBuf}};
use std::os::unix::fs::{OpenOptionsExt,PermissionsExt};

const ORIGINAL:&[u8]=b"synthetic original bytes to retain";
const OPTIMIZED:&[u8]=b"smaller";

fn private_directory(path:&Path) {
    std::fs::create_dir(path).unwrap();
    std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o700)).unwrap();
}
fn fixture_file(path:&Path,bytes:&[u8]) {
    let mut file=std::fs::OpenOptions::new().read(true).write(true).create_new(true).mode(0o600).open(path).unwrap();
    file.write_all(bytes).unwrap();
}
struct Fixture {root:tempfile::TempDir,view:TransactionView}
impl Fixture {
    fn new()->Self {
        let root=tempfile::tempdir().unwrap();
        for name in ["source","candidates","state","retention"] {private_directory(&root.path().join(name));}
        fixture_file(&root.path().join("source/original.bin"),ORIGINAL);
        fixture_file(&root.path().join("candidates/candidate.bin"),OPTIMIZED);
        let signals=SignalState::default();
        let body=TransactionBody {
            source:diag(fs::snapshot(&root.path().join("source/original.bin"),&signals,1024)).unwrap(),
            candidate:diag(fs::snapshot(&root.path().join("candidates/candidate.bin"),&signals,1024)).unwrap(),
            state:diag(fs::directory(&root.path().join("state"))).unwrap(),
            retention:diag(fs::directory(&root.path().join("retention"))).unwrap(),
            limits:TransactionLimits {maximum_file_bytes:1024,free_space_reserve_bytes:1024,journal_budget_bytes:1_048_576},
        };
        Self {root,view:TransactionView {fingerprint:"a".repeat(64),authorization_id:"b".repeat(64),body,video_action:None,media_validation:None}}
    }
    fn source(&self)->PathBuf {self.root.path().join("source/original.bin")}
    fn namespace(&self)->PathBuf {self.root.path().join("retention").join(&self.view.fingerprint)}
    fn records(&self)->Vec<ReplacementEvent> {
        status_for(&self.view.body.state,&self.view.fingerprint,self.view.body.limits.journal_budget_bytes).unwrap()
    }
}

#[test]
fn private_apply_and_restore_keep_both_objects_across_new_rename_bindings() {
    let fixture=Fixture::new();let signals=SignalState::default();
    assert_eq!(apply_shared(&fixture.view,&signals,&||Ok(())).unwrap().phase,"committed");
    assert_eq!(std::fs::read(fixture.source()).unwrap(),OPTIMIZED);
    assert_eq!(std::fs::read(fixture.namespace().join("original")).unwrap(),ORIGINAL);
    restore_shared(&fixture.view,&signals).unwrap();
    assert_eq!(std::fs::read(fixture.source()).unwrap(),ORIGINAL);
    assert_eq!(std::fs::read(fixture.namespace().join("optimized-after-restore")).unwrap(),OPTIMIZED);
    assert!(!fixture.namespace().join("original").exists());
    assert_eq!(fixture.records().last().unwrap().phase,"restored");
}

#[test]
fn staged_corruption_after_review_stops_before_original_retention() {
    let fixture=Fixture::new();let signals=SignalState::default();let injected=Cell::new(false);
    let result=apply_shared(&fixture.view,&signals,&||{
        // Existing media revalidation boundary; no new production fault hook.
        let staged=fixture.namespace().join("replacement");
        if staged.try_exists()?&&!injected.get() {std::fs::write(staged,b"changed")?;injected.set(true);}
        Ok(())
    });
    assert!(injected.get()&&result.is_err());
    assert_eq!(std::fs::read(fixture.source()).unwrap(),ORIGINAL);
    assert!(!fixture.namespace().join("original").exists());
    assert_eq!(std::fs::read(fixture.namespace().join("replacement")).unwrap(),b"changed");
    assert_eq!(fixture.records().last().unwrap().phase,"retain_pending");
}

#[test]
fn retained_held_bytes_must_match_even_when_metadata_binding_is_current() {
    let fixture=Fixture::new();let signals=SignalState::default();
    let mut held=diag(fs::open_bound(&fixture.view.body.source)).unwrap();
    let properties=diag(super::super::super::mutation::properties(&held)).unwrap();
    private_directory(&fixture.namespace());
    let retained=fixture.namespace().join("original");std::fs::rename(fixture.source(),&retained).unwrap();
    let mut binding=diag(fs::snapshot(&retained,&signals,1024)).unwrap();
    check_held_subject(&mut held,&binding,&properties,1024,&signals).unwrap();
    let expected=binding.blake3;
    std::fs::write(&retained,vec![b'x';ORIGINAL.len()]).unwrap();
    binding=diag(fs::snapshot(&retained,&signals,1024)).unwrap();
    binding.blake3=expected; // Isolate bytes from an otherwise current metadata pin.
    diag(fs::check_file(&held,&binding)).unwrap();
    let error=check_held_subject(&mut held,&binding,&properties,1024,&signals).unwrap_err();
    assert!(error.to_string().contains("held replacement bytes changed"));
    assert!(!fixture.source().exists()&&retained.is_file());
}

#[test]
fn late_xattrs_cannot_be_accepted_by_refreshing_only_the_metadata_binding() {
    let fixture=Fixture::new();let signals=SignalState::default();
    let mut held=diag(fs::open_bound(&fixture.view.body.source)).unwrap();
    let expected=diag(super::super::super::mutation::properties(&held)).unwrap();
    rustix::fs::fsetxattr(&held,std::ffi::OsStr::new("user.optiflow_integrity"),b"late",rustix::fs::XattrFlags::empty()).unwrap();
    let binding=diag(fs::snapshot(&fixture.source(),&signals,1024)).unwrap();
    diag(fs::check_file(&held,&binding)).unwrap();
    let error=check_held_subject(&mut held,&binding,&expected,1024,&signals).unwrap_err();
    assert!(error.to_string().contains("held replacement properties changed"));
    assert_eq!(std::fs::read(fixture.source()).unwrap(),ORIGINAL);
}

#[test]
fn current_path_directory_cannot_substitute_for_a_different_held_directory() {
    let fixture=Fixture::new();let path=fixture.namespace();private_directory(&path);
    let held=artifact::open_directory(&path).unwrap();
    std::fs::rename(&path,fixture.root.path().join("old-namespace")).unwrap();
    private_directory(&path);let current=diag(fs::directory(&path)).unwrap();
    diag(fs::check_directory(&current)).unwrap();
    assert!(check_directory_handle(&held,&current).is_err());
}

#[test]
fn restore_collision_retains_original_optimized_object_and_pending_evidence() {
    let fixture=Fixture::new();let signals=SignalState::default();
    apply_shared(&fixture.view,&signals,&||Ok(())).unwrap();
    let collision=fixture.namespace().join("optimized-after-restore");fixture_file(&collision,b"do not overwrite");
    assert!(restore_shared(&fixture.view,&signals).is_err());
    assert_eq!(std::fs::read(fixture.source()).unwrap(),OPTIMIZED);
    assert_eq!(std::fs::read(fixture.namespace().join("original")).unwrap(),ORIGINAL);
    assert_eq!(std::fs::read(collision).unwrap(),b"do not overwrite");
    assert_eq!(fixture.records().last().unwrap().phase,"restore_pending");
}
